import {useState} from 'react';
import {User} from '../../../../zustand/userStore';
import {TouchableOpacity, View, Image} from 'react-native';
import TextCM from '../../../components/Text';
import {CheckBox} from '@ui-kitten/components';
import {styles} from './styles';
import {String} from '../../../../constants';

type Props = {
  item: User;
  isSelected: boolean;
  toogleChooseUser: (item: User, isSelected: boolean) => void;
};
const UserItem = ({item, isSelected, toogleChooseUser}: Props) => {
  return (
    <TouchableOpacity
      style={styles.item}
      onPress={() => toogleChooseUser(item, isSelected)}
      activeOpacity={0.7}>
      <Image
        source={{uri: item?.image_url || String.DEFAULT_IMAGE}}
        style={styles.avatar}
      />

      <View style={{flex: 1}}>
        <TextCM style={styles.name}>
          {item.first_name || '' + ' ' + item?.last_name ? item.last_name : ''}
        </TextCM>
        <TextCM style={styles.desc}>{item.email}</TextCM>
      </View>

      <CheckBox
        checked={isSelected}
        onChange={() => toogleChooseUser(item, isSelected)}
        style={styles.checkbox}></CheckBox>
    </TouchableOpacity>
  );
};

export default UserItem;
