import {StyleSheet, FlatList} from 'react-native';
import HeaderConversation from './component/header-conversation';
import ChatItem from './component/chat-item';
import {useEffect, useState} from 'react';
import {useChatService} from '../../../hooks/apiHooks/useAccountInfoServices';
import {
  IConversation,
  IConversationResponse,
} from '../../../model/interface/chat.interface';
import Toast from 'react-native-toast-message';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useAppSelector} from '../../../hooks/useRedux';
import {useChatStore} from '../../../zustand/chatStore.ts';
import {
  initializeWebSocketListeners,
  useWebSocketStore,
} from '../../../zustand/useWebSocketStore.ts';
import {useShallow} from 'zustand/react/shallow';
import {userUserStore} from '../../../zustand/userStore.ts';

export default function ListConversation() {
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const accessToken = useAppSelector(state => state.common.accessToken);
  const {listUser} = userUserStore();
  const chatService = useChatService();

  const connectWebSocket = useWebSocketStore(state => state.connectWebSocket);
  const disconnectWebSocket = useWebSocketStore(
    state => state.disconnectWebSocket,
  );
  const {isConnected, lastMessage, error} = useWebSocketStore(
    useShallow(state => ({
      isConnected: state.isConnected,
      lastMessage: state.lastMessage,
      error: state.error,
    })),
  );

  const {
    currentConversationId,
    listMessage,
    listConversation,
    listCurrentViewConversation,
    setListConversation,
    setListCurrentViewConversation,
    setListConversationUnread,
    setListMessage,
  } = useChatStore();
  useState<IConversation[]>([]);

  const getListConversation = async () => {
    try {
      const res = (await chatService.getListConversation(
        dataAccount.id || 0,
      )) as IConversationResponse;
      const data = res.data;
      data.sort((a: IConversation, b: IConversation) => {
        const timeA = new Date(a.lastMessage.timestamp).getTime();
        const timeB = new Date(b.lastMessage.timestamp).getTime();
        return timeB - timeA;
      });
      if (data) {
        setListConversation(data);
        setListCurrentViewConversation(data);
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Lỗi khi lấy danh sách cuộc trò chuyện',
        });
      }
    } catch (error) {
      console.error('getListConversation: ', error);
    }
  };

  useEffect(() => {
    if (listConversation.length) {
      listConversation.forEach(item => {
        item.participants.forEach(participant => {
          if (participant.user_id) {
            const user = listUser.find(
              user => user.user_id === participant.user_id,
            );
            if (user) {
              participant.user = user;
            }
          }
        });
      });
    }
  }, [listConversation]);

  useEffect(() => {
    getListConversation();
    return () => {
      disconnectWebSocket();
    };
  }, []);

  useEffect(() => {
    if (accessToken) {
      initializeWebSocketListeners();
      connectWebSocket(accessToken);
    } else {
      useWebSocketStore.getState().disconnectWebSocket();
    }
  }, [accessToken]);

  const handleMessage = async (message: any) => {
    try {
      if (message?.action === 'NEW_CONVERSATION') {
        setListConversation([message.conversation, ...listConversation]);
      } else if (message?.action === 'SEND') {
        const newListConversation = listConversation.map(item => {
          if (item.id === message?.conversationId) {
            const tempText = item.lastMessage.text;
            const jsonText = JSON.parse(tempText);
            jsonText.text = message?.content?.text;

            item.lastMessage.text = JSON.stringify(jsonText);
            item.lastMessage.timestamp = message?.timestamp;
          }
          return item;
        });
        if (currentConversationId === message?.conversationId) {
          const newListMessage = [
            {
              message_id: message.id,
              sender_id: message?.from?.userId,
              message_content: JSON.stringify(message?.content),
              timestamp: message.timestamp,
              username: message?.from?.username,
              reply_to: null,
              status: message?.status,
              sequence: message?.sequence,
            },
            ...listMessage,
          ];
          setListMessage(newListMessage);
        }
        setListConversation(newListConversation);
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Lỗi gửi gửi nhận tin nhắn',
      });
      console.log(error);
    }
  };

  useEffect(() => {
    if (isConnected && lastMessage) {
      handleMessage(lastMessage);
    }
  }, [lastMessage]);

  return (
    <SafeAreaView style={styles.container}>
      <HeaderConversation />
      <FlatList
        data={listCurrentViewConversation}
        renderItem={({item}) => <ChatItem item={item} />}
        keyExtractor={item => item.id}
        showsVerticalScrollIndicator={false}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
  },
});
