import {create} from 'zustand';

export interface User {
  user_id: number;
  first_name?: string;
  last_name: string;
  email: string;
  image_url?: string;
  cust_id: number;
  org_in: string;
}
interface UserStore {
  listUser: User[];
  setListUser: (listUser: User[]) => void;
}

const initialSettingState = {
  listUser: [],
};

export const userUserStore = create<UserStore>((set, get) => ({
  ...initialSettingState,
  setListUser: (listUser: User[]) => set({listUser}),
}));
