import {Icon} from '@ui-kitten/components';
import {useEffect, useState} from 'react';
import {
  View,
  Text,
  TextInput,
  FlatList,
  TouchableOpacity,
  Image,
  SafeAreaView,
} from 'react-native';
import {useNavigation} from '@react-navigation/native';
import {User, userUserStore} from '../../../zustand/userStore';
import useDebounce from '../../../hooks/useDebounce';
import UserItem from './user-item';
import TextCM from '../../components/Text';
import {styles} from './styles';
import {Color, NavigationName, String} from '../../../constants';
import {useAppSelector} from '../../../hooks/useRedux';
import Toast from 'react-native-toast-message';

export default function CreatGroupChat() {
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const navigation = useNavigation<any>();
  const {listUser} = userUserStore();
  const [currentListUser, setCurrentListUser] = useState<User[]>([]);
  const [textSearch, setTextSearch] = useState('');
  const textSearchDebounce = useDebounce(textSearch, 500);
  const [listChosen, setListChosen] = useState<User[]>([]);
  const handleRemoveUser = (userId: any) => {
    setListChosen(prevList => prevList.filter(user => user.user_id !== userId));
  };

  useEffect(() => {
    if (!textSearchDebounce) {
      setCurrentListUser(listUser);
    }
    const lowerCaseQuery = textSearchDebounce.toLowerCase();
    const newList = listUser.filter(user => {
      const fullName = `${user.first_name || ''} ${
        user.last_name || ''
      }`.toLowerCase();
      const email = user.email.toLowerCase();
      return (
        fullName.includes(lowerCaseQuery) || email.includes(lowerCaseQuery)
      );
    });
    setCurrentListUser(newList);
  }, [textSearchDebounce]);

  const toogleChooseUser = (item: User, isSelected: boolean) => {
    if (item.user_id === dataAccount?.id) {
      Toast.show({
        type: 'error',
        text1: 'Bạn đã có trong cuộc trò chuyện',
      });
      return;
    }
    if (isSelected) {
      setListChosen(prev => prev.filter(x => x.user_id !== item.user_id));
    } else {
      setListChosen(prev => [item, ...prev]);
    }
  };

  const createAGroup = async () => {
    if (listChosen.length > 1) {
      const listId = listChosen.map(item => item.user_id);
      navigation.navigate(NavigationName.Conversation, {
        targetId: listId,
        conversationName: `Group Chat (${listId.length})`,
      });
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={styles.cancel}>Huỷ</Text>
        </TouchableOpacity>
        <Text style={styles.title}>Chọn Người</Text>
        <TouchableOpacity onPress={createAGroup}>
          <Text
            style={[
              styles.next,
              {color: listChosen.length > 0 ? '#007AFF' : '#ccc'},
            ]}>
            Tiếp
          </Text>
        </TouchableOpacity>
      </View>
      <View
        style={{
          flexDirection: 'row',
          columnGap: 16,
          paddingHorizontal: 16,
          marginBottom: 10,
          justifyContent: 'space-between',
          alignItems: 'center',
          backgroundColor: Color.White,
        }}>
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            backgroundColor: '#F0F0F0',
            borderRadius: 20,
            paddingHorizontal: 10,
            flex: 1,
            columnGap: 8,
          }}>
          <TouchableOpacity>
            <Icon name="search-outline" width={20} height={20} />
          </TouchableOpacity>
          <TextInput
            value={textSearch}
            style={{
              flex: 1,
              height: 40,
              fontSize: 16,
            }}
            placeholder="Tìm kiếm"
            autoFocus={true}
            onChange={e => setTextSearch(e.nativeEvent.text)}
          />
        </View>
      </View>
      <View style={styles.chosenListContainer}>
        <FlatList
          horizontal={true}
          data={listChosen}
          keyExtractor={item => item.user_id?.toString()}
          renderItem={({item}) => (
            <TouchableOpacity
              style={styles.chosenItem}
              onPress={() => toogleChooseUser(item, true)}>
              <TouchableOpacity
                style={styles.chosenItemRemove}
                onPress={() => handleRemoveUser(item.user_id || '')}>
                <Icon name="close-circle" fill="gray" width={20} height={20} />
              </TouchableOpacity>
              <Image
                source={{uri: item?.image_url || String.DEFAULT_IMAGE}}
                style={styles.chosenAvatar}
              />

              <TextCM style={styles.chosenName} numberOfLines={1}>
                {item.first_name || '' + ' ' + item?.last_name
                  ? item.last_name
                  : ''}
              </TextCM>
            </TouchableOpacity>
          )}
        />
      </View>

      {/* List */}
      <FlatList
        data={currentListUser}
        renderItem={({item}) => (
          <UserItem
            item={item}
            toogleChooseUser={toogleChooseUser}
            isSelected={listChosen.some(
              chosenUser => chosenUser.user_id === item.user_id,
            )}
          />
        )}
        keyExtractor={item => item.user_id?.toString()}
      />
    </SafeAreaView>
  );
}
