import {create} from 'zustand';
import {IConversation, Message} from '../model/interface/chat.interface';

interface ChatStore {
  currentConversationId?: string;
  listMessage: Message[];
  listCurrentViewConversation: IConversation[];
  listConversation: IConversation[];
  listConversationUnread: IConversation[];
  listConversationDraft: IConversation[];
  setCurrentConversationId: (conversationId: string) => void;
  setListMessage: (listMessage: Message[]) => void;
  setListConversation: (listConversation: IConversation[]) => void;
  setListConversationUnread: (listConversationUnread: IConversation[]) => void;
  setListConversationDraft: (listConversationDraft: IConversation[]) => void;
  setListCurrentViewConversation: (listConversation: IConversation[]) => void;
}

const initialSettingState = {
  currentConversationId: '',
  listMessage: [],
  listConversation: [],
  listConversationUnread: [],
  listConversationDraft: [],
  listCurrentViewConversation: [],
};

export const useChatStore = create<ChatStore>((set, get) => ({
  ...initialSettingState,
  setListConversation: (listConversation: IConversation[]) => {
    set({listConversation: listConversation});
  },
  setListConversationUnread: (listConversationUnread: IConversation[]) => {
    set({listConversationUnread: listConversationUnread});
  },
  setListConversationDraft: (listConversationDraft: IConversation[]) => {
    set({listConversationDraft: listConversationDraft});
  },
  setListCurrentViewConversation: (listConversation: IConversation[]) => {
    set({listCurrentViewConversation: listConversation});
  },
  setListMessage: (listMessage: Message[]) => {
    set({listMessage: listMessage});
  },
  setCurrentConversationId: (conversationId: string) => {
    set({currentConversationId: conversationId});
  },
}));
