import {Image, TextInput, TouchableOpacity, View} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import TextCM from '../../../../components/Text';
import {Icon} from '@ui-kitten/components';
import {useNavigation} from '@react-navigation/native';
import {useAppSelector} from '../../../../../hooks/useRedux';
import {NavigationName, String} from '../../../../../constants';
import {useRef, useState} from 'react';
import {styles} from './styles';
import {listButtonFilter} from './helper';
import ButtonFilter from './button-filter';
import {useChatStore} from '../../../../../zustand/chatStore.ts';

type Props = {};
const HeaderConversation = ({}: Props) => {
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const {
    listConversation,
    listConversationUnread,
    listConversationDraft,
    setListCurrentViewConversation,
  } = useChatStore();
  const navigation = useNavigation<any>();
  const insets = useSafeAreaInsets();
  const textInputRef = useRef<TextInput>(null);
  const [indexActive, setIndexActive] = useState(0);

  return (
    <>
      <View style={[styles.header, {paddingTop: insets.top > 0 ? 0 : 10}]}>
        <View style={styles.headerLeft}>
          <Image
            source={{
              uri: dataAccount.imageUrl
                ? dataAccount.imageUrl
                : String.DEFAULT_IMAGE,
            }}
            style={styles.profileImage}
          />
          <TextCM style={styles.headerTitle}>Đoạn chat</TextCM>
        </View>
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            columnGap: 10,
          }}>
          <TouchableOpacity
            style={styles.composeButton}
            onPress={() => navigation.navigate(NavigationName.CreatGroupChat)}>
            <Icon name="edit" width={20} height={20} />
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.composeButton}
            onPress={() => navigation.goBack()}>
            <Icon name="home" width={20} height={20} />
          </TouchableOpacity>
        </View>
      </View>

      <View style={styles.searchContainer}>
        <TouchableOpacity
          style={styles.searchBar}
          onPress={() =>
            navigation.navigate(NavigationName.SearchConversation)
          }>
          <TextInput
            ref={textInputRef}
            style={styles.searchInput}
            placeholder="Tìm kiếm người hoặc cuộc hội thoại"
            placeholderTextColor="#999"
            onFocus={() => {
              textInputRef.current?.blur();
              navigation.navigate(NavigationName.SearchConversation);
            }}
          />
        </TouchableOpacity>
      </View>

      <View style={styles.filterContainer}>
        {listButtonFilter.map((item, index) => (
          <ButtonFilter
            active={index === indexActive}
            label={item.label}
            key={index}
            onPress={() => {
              setIndexActive(index);
              switch (item.key) {
                case 'all':
                  setListCurrentViewConversation(listConversation);
                  break;
                case 'unread':
                  setListCurrentViewConversation(listConversationUnread);
                  break;
                case 'draft':
                  setListCurrentViewConversation(listConversationDraft);
                  break;
                default:
                  setListCurrentViewConversation(listConversation);
                  break;
              }
            }}
          />
        ))}
      </View>
    </>
  );
};

export default HeaderConversation;
