import {Text, View} from 'react-native';
import {styles} from './styles';
import TextCM from '../../../../components/Text';
import {Chat, Message} from '../../../../../model/interface/chat.interface';

type Props = {
  item: Message;
  type: 'me' | 'other' | 'reply';
};
const MessageItem = ({item, type}: Props) => {
  const content = JSON.parse(item.message_content || '{}');

  if (type === 'reply') {
    return (
      <View style={styles.replyContainer}>
        <View style={styles.replyMessageBubble}>
          <TextCM style={styles.replyText}>{content?.text}</TextCM>
        </View>
        <View style={styles.replyInfo}>
          <TextCM style={styles.replyInfoText}>{item.username}</TextCM>
        </View>
      </View>
    );
  }

  return (
    <View style={[styles.messageRow, styles.otherMessageRow]}>
      <View style={[styles.messageBubble, styles.otherMessageBubble]}>
        <TextCM style={[styles.messageText, styles.otherMessageText]}>
          {content?.text}
        </TextCM>
      </View>
      <View style={styles.replyInfo}>
        <View style={{flex: 1}}/>
        <TextCM style={[styles.replyInfoText, {textAlign: 'right'}]}>
          {'Bạn'}
        </TextCM>
      </View>
    </View>
  );
};
export default MessageItem;
