import React, {useEffect, useRef, useState} from 'react';
import {
  View,
  Image,
  TouchableOpacity,
  SafeAreaView,
  FlatList,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {useNavigation, useRoute} from '@react-navigation/native';
import {styles} from './styles';
import {useChatService} from '../../../hooks/apiHooks/useAccountInfoServices';
import {useUserService} from '../../../hooks/apiHooks/useAPI';
import MessageItem from './component/message-item';
import {
  Chat,
  Message,
  ParticipantListConversation,
} from '../../../model/interface/chat.interface';
import TextCM from '../../components/Text';
import {useAppSelector} from '../../../hooks/useRedux';
import {Icon} from '@ui-kitten/components';
import MessageInput from './component/message-input';
import Toast from 'react-native-toast-message';
import Avatar from '../../components/Avatar';
import {User, userUserStore} from '../../../zustand/userStore';
import {useChatStore} from '../../../zustand/chatStore';

const Conversation = () => {
  const {dataAccount} = useAppSelector(state => state.account);
  const {listMessage, setListMessage} = useChatStore();
  const route = useRoute<any>();
  const insets = useSafeAreaInsets();
  const navigation = useNavigation();
  const [participants, setParticipants] = useState<
    ParticipantListConversation[]
  >([]);
  const {listUser} = userUserStore();
  const [isTyping, setIsTyping] = useState(false);
  const ChatService = useChatService();

  const onEndReachedCalledDuringMomentum = useRef(true);

  const conversationId = route?.params?.conversationId;
  const conversationName = route?.params?.conversationName;
  const targetId = route?.params?.targetId;

  const getHistoryChat = async () => {
    try {
      if (!conversationId) {
        setListMessage([]);
        const usersChatWith = targetId
          .map((id: number) =>
            listUser.find((user: User) => user.user_id === id),
          )
          .filter(Boolean);
        const myProfile = listUser.find(
          (user: User) => user.user_id === dataAccount?.id,
        );
        setParticipants([
          ...usersChatWith.map((user: User) => ({
            user_id: user.user_id || 0,
            i_nick: `${usersChatWith?.first_name || ''} ${
              usersChatWith?.last_name || ''
            }`?.trim(),
            user,
          })),
          {
            user_id: dataAccount?.id || 0,
            i_nick: `${myProfile?.first_name || ''} ${
              myProfile?.last_name || ''
            }`?.trim(),
            user: myProfile,
          },
        ]);
        return;
      } else {
        const res = await ChatService.getHistoryChat(conversationId, 50, 1);
        if (res.data) {
          const data = res.data as Chat;
          if (data.messages.length > 0) {
            const newMessage = data.messages.reverse();
            setListMessage(newMessage);
          }
          const newParticipants = data.participants.map(
            (item: ParticipantListConversation) => {
              const findedUser = listUser.find(
                (user: User) => user.user_id === item.user_id,
              );
              if (findedUser) {
                item.user = findedUser;
              }
              return item;
            },
          );
          setParticipants(newParticipants);
        }
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Không thể lấy cuộc trò chuyện',
      });
    }
  };

  useEffect(() => {
    getHistoryChat();
    // getInfo();
  }, []);

  const getConversationName = () => {
    if (participants.length > 2) {
      const names = participants.map(
        participant =>
          participant?.user?.first_name ||
          '' + ' ' + participant?.user?.last_name ||
          '',
      );
      return names.join(', ');
    } else {
      const findedUser = participants.find(
        (item: ParticipantListConversation) => item.user_id !== dataAccount?.id,
      );
      return (
        findedUser?.user?.first_name ||
        '' + ' ' + findedUser?.user?.last_name ||
        ''
      );
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={[styles.header, {paddingTop: insets.top > 0 ? 0 : 10}]}>
        <TouchableOpacity
          style={styles.backButton}
          onPress={() => navigation.goBack()}>
          <Icon name="arrow-ios-back" width={20} height={20} />
        </TouchableOpacity>

        <View style={styles.userInfo}>
          <Avatar participants={participants} />
          <View style={styles.userTextInfo}>
            <TextCM style={styles.userName}>
              {conversationName || getConversationName()}
            </TextCM>
            {/* <TextCM style={styles.userStatus} numberOfLines={1}>
              {'none status'}
            </TextCM> */}
          </View>
        </View>

        <View style={styles.headerActions}>
          <TouchableOpacity style={styles.headerButton}>
            <Icon name="phone" width={20} height={20} />
          </TouchableOpacity>
          <TouchableOpacity style={styles.headerButton}>
            <Icon name="video" width={20} height={20} />
          </TouchableOpacity>
          <TouchableOpacity style={styles.headerButton}>
            <Icon name="info" width={20} height={20} />
          </TouchableOpacity>
        </View>
      </View>

      {/* Chat Messages */}
      <View style={styles.chatContainer}>
        <FlatList
          data={listMessage}
          renderItem={({item}) => (
            <MessageItem
              item={item}
              type={dataAccount.id == item.sender_id ? 'me' : 'reply'}
            />
          )}
          keyExtractor={item => item.message_id + ''}
          contentContainerStyle={styles.messagesList}
          showsVerticalScrollIndicator={false}
          // onEndReached={() => {
          //   if (!onEndReachedCalledDuringMomentum.current) {
          //     // loadMore();
          //     onEndReachedCalledDuringMomentum.current = true;
          //   }
          // }}
          // onMomentumScrollBegin={() => {
          //   onEndReachedCalledDuringMomentum.current = false;
          // }}
          inverted={true}
        />

        {/* Time Divider */}
        {/* <View style={styles.timeDivider}>
          <TextCM style={styles.timeDividerText}>13:38</TextCM>
        </View> */}
      </View>

      {/* Message Input */}
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        // keyboardVerticalOffset={insets.bottom}
        style={styles.inputContainer}>
        <MessageInput
          participants={participants}
          conversationId={conversationId}
          conversationName={conversationName}
        />
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
};

export default Conversation;
