import {TouchableOpacity, View} from 'react-native';
import TextCM from '../../../../components/Text';
import {IConversation} from '../../../../../model/interface/chat.interface';
import {NavigationName} from '../../../../../constants';
import {styles} from './styles';
import {DateUtils} from '../../../../../utils';
import {useNavigation} from '@react-navigation/native';
import Avatar from '../../../../../app/components/Avatar';
import {useChatStore} from '../../../../../zustand/chatStore';

type Props = {
  item: IConversation;
};
const ChatItem = ({item}: Props) => {
  const navigation = useNavigation<any>();
  const parseLastMessage = JSON.parse(item?.lastMessage.text || '{}');
  const lastMessage = parseLastMessage?.text || '';
  const {setCurrentConversationId} = useChatStore();
  return (
    <TouchableOpacity
      style={styles.chatItem}
      onPress={() => {
        setCurrentConversationId(item.id);
        navigation.navigate(NavigationName.Conversation, {
          conversationId: item.id,
          conversationName: item.conversationName,
        });
      }}>
      <Avatar participants={item.participants} />

      <View style={styles.chatContent}>
        <View style={styles.chatHeader}>
          <TextCM style={styles.chatName} numberOfLines={1}>
            {item.conversationName}
          </TextCM>
          <TextCM style={styles.chatTime}>
            {DateUtils.convertDateToDDMMYYYY_H_M(item?.lastMessage?.timestamp)}
          </TextCM>
        </View>
        <View style={styles.chatFooter}>
          <TextCM style={styles.chatMessage} numberOfLines={1}>
            {`${item.lastMessage.username}:`} {lastMessage}
          </TextCM>
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default ChatItem;
